def algorithm(func, dim, lb, ub, budget, rng):
    def Rosenbrock(x):
        return func(x)

    def gradient(x):
        g = np.zeros(dim)
        for i in range(dim - 1):
            g[i] += 400 * (x[i + 1] - x[i]**2) * (2 * x[i] - 1)
            g[i + 1] += 200 * (x[i + 1] - x[i]**2)
        return g

    def clip(x):
        return np.clip(x, lb, ub)

    best = np.random.uniform(lb, ub, dim)
    best_f = Rosenbrock(best)

    for _ in range(budget):
        candidate = best + rng.normal(0, 1e-2, size=dim)
        candidate = clip(candidate)

        f_candidate = Rosenbrock(candidate)

        if f_candidate < best_f:
            best = candidate
            best_f = f_candidate

        gradient_step = -gradient(best) * 1e-3
        local_best = best + gradient_step
        local_best = clip(local_best)
        local_best_f = Rosenbrock(local_best)

        if local_best_f < best_f:
            best = local_best
            best_f = local_best_f

    return best

def algorithm(func, dim, lb, ub, budget, rng):
    def evaluate(x):
        return func(x)

    def mutate(x):
        v = np.random.uniform(lb, ub, size=dim)
        for i in range(dim):
            if rng.random() < 0.1:
                x[i] += (v[i] - x[i]) * rng.uniform(0, 1)
        return x

    def crossover(x, y):
        v = np.zeros(dim)
        for i in range(dim):
            v[i] = x[i] + (y[i] - x[i]) * rng.uniform(0, 1)
            if rng.random() < 0.5:
                v[i], x[i] = x[i], v[i]
        return v

    x = np.array([ub] * dim)
    temperature = 100
    best_x = x.copy()
    for _ in range(budget):
        y = mutate(x)
        z = crossover(y, best_x)
        fy = evaluate(y)
        fz = evaluate(z)
        if fy < fz:
            x = y
        elif np.random.uniform(0, 1) < np.exp((fy - fz) / temperature):
            x = z
        temperature *= 0.9999
        if evaluate(best_x) > evaluate(x):
            best_x = x.copy()
    return best_x
